const i = $input.first().json;
const periodo = String(i.periodo ?? '').trim();
const hoy = $now.setZone('Europe/Madrid').startOf('day');
const fmt = (d) => d.toFormat('yyyy-MM-dd');
let desde;
let hasta = hoy;

switch (periodo) {
  case 'hoy': desde = hoy; break;
  case 'ayer': desde = hasta = hoy.minus({ days: 1 }); break;
  case 'esta_semana': desde = hoy.startOf('week'); break;
  case 'semana_pasada':
    desde = hoy.startOf('week').minus({ weeks: 1 });
    hasta = desde.plus({ days: 6 });
    break;
  case 'este_mes': desde = hoy.startOf('month'); break;
  case 'mes_pasado':
    desde = hoy.startOf('month').minus({ months: 1 });
    hasta = desde.endOf('month').startOf('day');
    break;
  case 'ultimos_dias': {
    const n = Number(i.dias);
    if (!Number.isInteger(n) || n < 1 || n > 366) throw new Error(`Dias no válido: ${i.dias}`);
    desde = hoy.minus({ days: n - 1 });
    break;
  }
      case 'rango': {
    desde = DateTime.fromISO(String(i.desde), { zone: 'Europe/Madrid' });
    hasta = DateTime.fromISO(String(i.hasta), { zone: 'Europe/Madrid' });
    if (!desde.isValid || !hasta.isValid) throw new Error(`Fechas no válidas: ${i.desde} / ${i.hasta}`);
    if (hasta > hoy) hasta = hoy;
    if (desde > hasta) throw new Error(`Rango no válido: ${i.desde} / ${i.hasta}`);
    break;
  }
  default:
    throw new Error(`Periodo desconocido: ${periodo}`);
}

return [{ json: { periodo, desde: fmt(desde), hasta: fmt(hasta) } }];

const f = $('Calcular fechas').first().json;
const ventas = $('Ventas del periodo').all();
const abonos = $('Abonos del periodo').all();
const formas = ['efectivo', 'tarjeta', 'bizum'];

const sumar = (items) => {
  const t = { efectivo: 0, tarjeta: 0, bizum: 0 };
  let n = 0;
  for (const it of items) {
    const r = it.json;
    if (r.importe === undefined || r.importe === null) continue;
    const forma = String(r.forma_pago ?? '').trim().toLowerCase();
    if (!formas.includes(forma)) {
      throw new Error(`Forma de pago desconocida: ${r.forma_pago}`);
    }
    t[forma] += Math.round(Number(r.importe) * 100);
    n++;
  }
  return { t, n };
};

const v = sumar(ventas);
const a = sumar(abonos);
const total = {};
for (const x of formas) total[x] = v.t[x] + a.t[x];

const suma = (o) => formas.reduce((s, x) => s + o[x], 0);
const fmt = (c) =>
  `${(c / 100).toLocaleString('es-ES', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  })} €`;
const bloque = (titulo, o) =>
  `${titulo}\n` +
  `  Efectivo: ${fmt(o.efectivo)}\n` +
  `  Tarjeta: ${fmt(o.tarjeta)}\n` +
  `  Bizum: ${fmt(o.bizum)}\n` +
  `  Total: ${fmt(suma(o))}`;

const fecha = (s) => s.split('-').reverse().join('/');
const rango = f.desde === f.hasta
  ? `El ${fecha(f.desde)}`
  : `Del ${fecha(f.desde)} al ${fecha(f.hasta)}`;

const movimientos = v.n + a.n;
const texto = movimientos > 0
  ? `${rango}\n\n` +
    bloque('Ventas directas', v.t) + '\n\n' +
    bloque('Abonos de apartados', a.t) + '\n\n' +
    bloque('Total', total)
  : `${rango}\n\nNo hubo movimientos`;

return [{ json: { periodo: f.periodo, desde: f.desde, hasta: f.hasta, ventas: v.n, abonos: a.n, movimientos, texto } }];
